import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0045 — Parità per costruzione tra desktop, workbench web e console","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0045-parita-per-costruzione.md","filePath":"adr/0045-parita-per-costruzione.md"}'),n={name:"adr/0045-parita-per-costruzione.md"};function c(d,e,r,l,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0045-—-parita-per-costruzione-tra-desktop-workbench-web-e-console" tabindex="-1">ADR-0045 — Parità per costruzione tra desktop, workbench web e console <a class="header-anchor" href="#adr-0045-—-parita-per-costruzione-tra-desktop-workbench-web-e-console" aria-label="Permalink to &quot;ADR-0045 — Parità per costruzione tra desktop, workbench web e console&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-11-02</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.7 e §2.8.3 (workbench web), §2.5 (core); A-03; estende ADR-0029, ADR-0030, ADR-0037 e ADR-0043</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no (cambia come si garantisce la parità, non le funzioni)</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Oggi la parità è già in buona parte strutturale: una sola UI (<code>packages/workbench</code>, montata da <code>mountWorkbench</code> su Wails e nel browser), una sola logica Go (<code>App.Services()</code> servita da Wails e dal dispatcher RPC del core WASM, con <code>TestDispatcherMatchesTheGeneratedBindings</code>), capability della UI (<code>platform/index.ts</code>, <code>Command.requires</code>), la porta <code>CloudPort</code> con due adattatori (<code>@memobrain/cloud-features</code>), contratti generati dall&#39;OpenAPI e il registro <code>shared/parity/features.yaml</code> controllato da <code>task parity</code>.</p><p>La revisione del 2026-11-02 ha trovato 13 divergenze, tutte nei punti ancora manuali:</p><ul><li>lo stato <code>yes</code> del workbench si eredita dal desktop senza prove: <code>tests.web</code> mescola console e workbench, e i pannelli cloud non hanno test sul core WebAssembly;</li><li>le azioni dei pannelli che non sono comandi («Apri» un mount, «Mantieni una copia», «Rimuovi da questo browser», «Nuovo vault») non hanno <code>requires</code> e il controllo non le vede; da lì vengono due difetti dei mount sul web;</li><li>controlli <code>kind === &#39;web&#39;</code> fuori da <code>platform/</code> e una capability dichiarata ma mai usata (<code>directoryPicker</code>);</li><li>l&#39;host web chiama i binding con stringhe e DTO scritti a mano; i nomi e i payload degli eventi sono copiati in più file Go e TS;</li><li>i DTO dei binding cloud sono diversi da quelli dell&#39;OpenAPI e <code>CoreCloudPort</code> li rimappa a mano;</li><li>politiche duplicate tra React e DOM (forza della passphrase nel gate di sblocco del web) e l&#39;elenco dei mount in tre implementazioni.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Capability con una sola fonte, nel core Go.</strong> <code>apps/desktop/internal/app/capabilities.go</code> (con varianti <code>_web</code>/<code>_native</code> per build tag) espone le capability tramite i binding; <code>Host</code> le dichiara accanto ai metodi che non supporta. <code>platform/index.ts</code> smette di tenere tabelle scritte a mano: <code>mountWorkbench</code> le legge dal core, le capability proprie del browser restano override dell&#39;host. Un test Go verifica che ogni metodo di <code>Host</code> che sul web non è disponibile abbia la sua capability <code>false</code>.</li><li><strong>Azioni dichiarative oltre ai comandi.</strong> <code>defineAction({ id, feature, requires, run })</code> e un componente <code>&lt;ActionButton id=… /&gt;</code> che nasconde o disabilita da solo l&#39;azione; il controllo di parità tratta le azioni come i comandi.</li><li><strong><code>FeatureId</code> generato.</strong> <code>task gen</code> genera da <code>features.yaml</code> il tipo <code>FeatureId</code> (TS) e le costanti Go; <code>Command</code>, <code>Action</code> e <code>skipOnWeb</code> ricevono <code>feature: FeatureId</code> obbligatorio: un&#39;azione senza voce nel registro non compila.</li><li><strong>Prove per superficie.</strong> Nel registro <code>tests</code> si divide in <code>desktop</code>, <code>workbench</code>, <code>console</code> e <code>cloud</code>. <code>workbench: yes</code> richiede almeno una prova sul core WebAssembly, altrimenti lo stato è <code>partial</code> con la motivazione; ogni rotta e azione della console è citata; una capability senza consumatori è un errore. Un mock REST condiviso permette di eseguire i pannelli cloud sul core vero.</li><li><strong>Client dell&#39;host web ed eventi generati.</strong> <code>task wailsjs</code> genera un client tipizzato dei binding per l&#39;host web (<code>web/src/workbench/core.gen.ts</code>, con limite di tempo); un generatore Go produce i nomi e i payload degli eventi Go→TS (<code>events.gen.ts</code>). Regole ESLint vietano nomi di binding o di eventi scritti a mano e <code>.kind ===</code> fuori da <code>platform/</code>.</li><li><strong>DTO dei binding cloud uguali all&#39;OpenAPI.</strong> I binding di gestione cloud restituiscono i tipi di <code>shared/go/apiclient</code>; <code>CoreCloudPort</code> diventa un passaggio senza mappature, e un test di tipo blocca la deriva.</li><li><strong>Ciclo di vita del cloud in <code>@memobrain/cloud-features</code>.</strong> Un solo componente <code>MountsList</code> per pannello del workbench, console e inviti; ESLint vieta le chiamate dirette alle API di gestione fuori dalla porta; la suite condivisa gira anche su <code>CoreCloudPort</code> sopra il core WASM.</li><li><strong>Politiche nel core.</strong> Forza della passphrase (§3.8.2), vault eliminato fuori dall&#39;app e regole di permanenza delle copie stanno in Go; React e il gate DOM mostrano soltanto errori tipizzati.</li><li><strong>Processo.</strong> Checklist di una funzione nuova: voce nel registro → <code>task gen</code> (<code>FeatureId</code>) → comando o azione con <code>feature</code> e <code>requires</code> → binding con DTO OpenAPI → prove per superficie → <code>task parity</code>. Il template degli ADR aggiunge la riga «Superfici».</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Solo correzioni puntuali dei gap</strong> — chiude i difetti di oggi ma non impedisce i prossimi: sono nati tutti nei punti dove la parità dipende dalla disciplina.</li><li><strong>Due UI separate per desktop e web</strong> — contraddice ADR-0029 e raddoppia il lavoro.</li><li><strong>Generare tutto dall&#39;OpenAPI</strong> — i binding locali (vault, editor, indice) non sono operazioni REST; il registro resta la fonte delle funzioni, l&#39;OpenAPI quella dei contratti cloud.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Implementazione in M12: punti 4–5 nell&#39;onda W4, punti 1–3 e 6–8 nell&#39;onda W5, punto 9 con la documentazione (W7).</li><li>Più codice generato (client dell&#39;host, eventi, <code>FeatureId</code>) e quindi più controlli in <code>task check-gen</code>.</li><li>La migrazione dei DTO procede un servizio alla volta; finché non è completa <code>CoreCloudPort</code> conserva le mappature residue, coperte dal test di tipo.</li></ul><h2 id="attuazione-m12-2026-11-03" tabindex="-1">Attuazione (M12, 2026-11-03) <a class="header-anchor" href="#attuazione-m12-2026-11-03" aria-label="Permalink to &quot;Attuazione (M12, 2026-11-03)&quot;">​</a></h2><ul><li>Punto 4 (M12-W4.2): <code>tests</code> diviso per superficie; <code>parity --check</code> rifiuta un «sì» sul workbench senza prova sul core WASM; mock REST validato sull&#39;OpenAPI (<code>web/e2e/cloudMock.ts</code>). 19 funzioni portate a <code>partial</code> perché senza prova.</li><li>Punto 5 (M12-W4.3): eventi dichiarati con <code>internal/events</code> e generati in <code>events.gen.ts</code>; client tipizzato dell&#39;host in <code>web/src/workbench/core.gen.ts</code>; regole ESLint.</li><li>Punto 1 (M12-W5.1): le capability stanno in un&#39;unica tabella Go (<code>internal/app/capabilities.go</code>) con le colonne desktop e web, invece che in file <code>_web</code>/<code>_native</code>: il generatore è un programma nativo e deve scrivere entrambe le colonne; la build sceglie la colonna con <code>isWeb</code>. I test falliscono se un metodo di <code>Host</code> non è classificato o se una capability è vera sul web per un metodo che lì fallisce.</li><li>Punti 2 e 3 (M12-W5.2): <code>FeatureId</code> generato da <code>features.yaml</code> (TS e Go); <code>Command.feature</code> obbligatorio per i 182 comandi; 13 azioni dichiarative (<code>defineAction</code>, <code>&lt;ActionButton&gt;</code>) al posto dei pulsanti dei pannelli. Oltre a <code>requires</code>, un&#39;azione può dichiarare <code>excludes</code> (offerta solo dove manca una capability: le alternative del browser come «Scarica una copia»).</li><li>Punto 7 (M12-W5.4): <code>MountsList</code> unico in <code>@memobrain/cloud-features</code>; regole ESLint sulle chiamate dirette; le suite condivise girano anche sul core WASM reale in Node (<code>task test-core</code>), con un cloud finto validato sull&#39;OpenAPI.</li><li>Punto 6 (M12-W5.3): pacchetto <code>internal/app/cloudapi</code>; <code>SearchDirectory</code> diviso in <code>SearchDirectoryUsers</code> e <code>SearchDirectoryGroups</code>, perché un binding non può restituire l&#39;unione dei due tipi.</li><li>Punto 8 (M12-W5.5): la politica della passphrase sta nel core (<code>crypto.ValidatePassphrase</code>, zxcvbn in Go, +774 kB gzip al core WASM, sotto il budget); <code>SyncAPI.CopyVerdict</code> decide se una copia del browser si può rimuovere. Restano nell&#39;host i marcatori in <code>localStorage</code> (la console gira senza core) e le decisioni dopo <code>vault:cloud-deleted</code>.</li></ul>',14)])])}const b=o(n,[["render",c]]);export{g as __pageData,b as default};
